function setSelectedTabFromStorage(){var selected_tab=readLocalStorage("selected_tab");if(selected_tab==null){setSelectedTab("default");}else{setSelectedTab(selected_tab);}}
function highlightText(name,query){var substring_index=name.toLowerCase().indexOf(query.toLowerCase());if(substring_index===-1){return name;}
var string=name.substring(0,substring_index)
+"<span class='yellow strong'>"
+name.substring(substring_index,substring_index+query.length)
+"</span>"
+name.substring(substring_index+query.length);return string;}
function findMembers(typeName,parentMembers,query){function getHref(parentName,parentMember){var stepBack='';let url=window.location.href;if(url.includes('classes/')||url.includes('prototypes/')||url.includes('types/')){stepBack='../';}
let members={'class_':'classes/','prototype':'prototypes/','type_':'types/'};for(let internalName in members){if(typeName==internalName){var href=stepBack+members[internalName]+parentName+'.html';if(parentMember){href+='#'+parentMember;}
return href;}}}
var parentList=document.querySelector('.docs-sidebar-list #list-'+typeName);parentList.innerHTML="";for(var parentSearchName in parentMembers){let parentName=parentSearchName.split('|')[0];let memberList=[];if(query.length>=2){parentMembers[parentSearchName].forEach(function(parentMember){if(parentMember.toLowerCase().indexOf(query.toLowerCase())!=-1){var memberListItem=document.createElement('li');memberListItem.classList.add('attribute');memberListItem.innerHTML='<a href="'+getHref(parentName,parentMember)+'">'
+highlightText(parentMember,query)+'</a>';memberList.push(memberListItem);}});}
if(memberList.length>0||parentSearchName.toLowerCase().indexOf(query.toLowerCase())!=-1){var parentListItem=document.createElement('li');var linkItem=document.createElement('a');linkItem.href=getHref(parentName,null);linkItem.innerHTML=highlightText(parentName,query);if(window.location.href.split("/").slice(-1)==(parentName+".html")){linkItem.classList.add('white','strong')}
parentListItem.appendChild(linkItem);parentList.appendChild(parentListItem);memberList.forEach(parentList.appendChild.bind(parentList));}}}
function searchInputEvent(){var query=document.getElementById("ref-search").value;writeLocalStorage("search_query",query);var date=new Date();writeLocalStorage("search_time",date.getTime());if(document.getElementById("runtime-page")){findMembers('class_',classAttributes,query)
document.querySelectorAll('.docs-sidebar-list ul:not(#list-class_) li').forEach(function(el){var name=el.dataset.name;var inner=name;display="block";if(query){let category=el.parentElement.id.split('-')[1];query=query.toLowerCase();if(query.startsWith('defines.')&&category!='defines'){display="none";}else{query=query.replace('defines.','');if(name.toLowerCase().includes(query)){var string=highlightText(name,query);inner=string;}else{display="none";}}}
el.children[0].innerHTML=inner;el.style.display=display;})}else if(document.getElementById("prototype-page")){findMembers('prototype',prototypeProperties,query);findMembers('type_',typeProperties,query);}}
function setSearchFromLocalStorage(){var search_query=readLocalStorage("search_query");if(search_query){var search_time=new Date(parseInt(readLocalStorage("search_time")));if(new Date().getTime()<search_time.getTime()+60*60*1000){document.getElementById("ref-search").value=search_query;}}
searchInputEvent();}
function setScrollPositionFromLocalStorage(){var sidebar_scroll=readLocalStorage("sidebar_scroll");if(sidebar_scroll){sidebar_scroll=parseInt(sidebar_scroll)
var list=document.getElementById('docs-sidebar-list');list.scrollTop=sidebar_scroll;}}
function setAnchorClass(){document.querySelectorAll('.target').forEach(function(el){el.classList.remove('target');});let target=window.location.hash.slice(1);if(target){let element=document.getElementById(target);if(element){element.classList.add("target");}}}
window.addEventListener('hashchange',setAnchorClass);window.addEventListener('load',function(){if(document.getElementById("auxiliary-page")){localStorage.setItem("auxiliary_body_wide","false");}
const reset=localStorage.getItem("body_wide_reset");if(reset==null||reset=="false"){localStorage.setItem("body_wide_reset","true");localStorage.setItem("runtime_body_wide","true");localStorage.setItem("prototype_body_wide","true");}
setBodyWidthFromLocalStorage();setSelectedTabFromStorage();setSidebarShownFromLocalStorage();setSearchFromLocalStorage();setScrollPositionFromLocalStorage();setStatusShownFromLocalStorage();document.getElementById("page-width-button").addEventListener('click',function(){var body_wide=readLocalStorage("body_wide")==="true";setBodyWidth(!body_wide);});let status_button=document.getElementById("page-status-button")
if(status_button!=null){status_button.addEventListener('click',function(){var status_shown=readLocalStorage("status_shown")==="true";setStatusShown(!status_shown);});}
document.getElementById("hide-sidebar-button").addEventListener('click',function(){setSidebarShown(false);});document.getElementById("show-sidebar-button").addEventListener('click',function(){setSidebarShown(true);});document.getElementById("ref-search").addEventListener('input',searchInputEvent);window.addEventListener('beforeunload',function(){var list=document.getElementById('docs-sidebar-list');writeLocalStorage("sidebar_scroll",list.scrollTop);});document.querySelectorAll(".class-attribute-table").forEach(function(el){var tab_default=el.querySelectorAll(".class-attributes-tab-default")[0];var tab_sorted=el.querySelectorAll(".class-attributes-tab-sorted")[0];if(tab_sorted&&tab_default){tab_sorted.addEventListener('click',function(){setSelectedTab("sorted");});tab_default.addEventListener('click',function(){setSelectedTab("default");});};});document.querySelectorAll(".floating-image-box").forEach(function(el){const image=el.querySelector("img");el.style.maxWidth=image.naturalWidth+"px";const text=el.parentElement.parentElement.querySelector(".text-next-to-image");text.style.minHeight=el.parentElement.clientHeight+"px";});document.querySelectorAll(".category-link").forEach(function(el){el.addEventListener('click',function(e){const list=document.getElementById(e.target.dataset.view);const sidebar=document.getElementById('docs-sidebar-list');sidebar.scrollTop=list.offsetTop-155;});});document.querySelectorAll(".collapse-link").forEach(function(el){el.addEventListener('click',function(e){const collapse=e.target.querySelector(".collapse-icon");const expand=e.target.querySelector(".expand-icon");const list=document.getElementById(e.target.dataset.view);if(e.target.dataset.collapsed=="true"){e.target.dataset.collapsed="false";collapse.style.display="inline";expand.style.display="none";list.style.display="block";}else{e.target.dataset.collapsed="true";collapse.style.display="none";expand.style.display="inline";list.style.display="none";};})});});